import{_ as t,c as a,o as r,ag as o}from"./chunks/framework.ARG558ZT.js";const u=JSON.parse('{"title":"Shared model and application foundations","description":"","frontmatter":{},"headers":[],"relativePath":"applied-ai/shared/index.md","filePath":"applied-ai/shared/index.md"}'),n={name:"applied-ai/shared/index.md"};function i(s,e,d,l,c,p){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="shared-model-and-application-foundations" tabindex="-1">Shared model and application foundations <a class="header-anchor" href="#shared-model-and-application-foundations" aria-label="Permalink to “Shared model and application foundations”">​</a></h1><p>A model proposes output; the application owns the task, identity, validated boundary and effects. The same rule applies to an answering model, a planner, a reranker and an n8n AI node. Inputs from sources, tool results, history and previous model responses remain <strong>untrusted data</strong>.</p><h2 id="one-coherent-prerequisite-chain" tabindex="-1">One coherent prerequisite chain <a class="header-anchor" href="#one-coherent-prerequisite-chain" aria-label="Permalink to “One coherent prerequisite chain”">​</a></h2><table tabindex="0"><thead><tr><th>Order</th><th>Teaching owner</th><th>Worked boundary</th></tr></thead><tbody><tr><td>1</td><td><a href="./../../python-for-ai/model-sdk.html">Model integration</a></td><td>Owned client, explicit one-attempt policy, structured classifier result and safe error vocabulary</td></tr><tr><td>2</td><td><a href="./../../python-for-ai/token-budgets.html">Tokens</a>, <a href="./../../python-for-ai/model-streaming.html">streaming</a></td><td>Count final payload; reserve output; distinguish pending draft, terminal result, refusal, incomplete and outage</td></tr><tr><td>3</td><td><a href="./../../python-for-ai/tool-boundaries.html">Tools</a>, <a href="./../../python-for-ai/history-and-workflows.html">history/state</a></td><td>Exact tool names/complete arguments/call identity; validated results; history is no authority</td></tr><tr><td>4</td><td><a href="./../../python-for-ai/prompt-injection-boundaries.html">Task-scoped injection boundary</a>, <a href="./../../python-for-ai/source-and-output-security.html">source/output sinks</a></td><td>Current tenant/subject scope, purpose-limited reads, fixed safe rendering and no arbitrary URL/shell fallback</td></tr><tr><td>5</td><td><a href="./../../python-for-ai/model-work-budgets.html">Admission/retries</a>, <a href="./../../python-for-ai/model-economics.html">task economics</a></td><td>Calls/bytes/time/spend are separate; reserve before work; unknown usage is not zero</td></tr><tr><td>6</td><td><a href="./../../python-for-ai/evaluation-lab.html">Evaluation</a>, <a href="./../../python-for-ai/evaluation-measurements.html">measurements</a>, <a href="./../../python-for-ai/workflow-diagnostics.html">diagnostics</a></td><td>Independent deterministic gates and semantic rubric; versioned cases, safe events and whole-task denominators</td></tr><tr><td>7</td><td><a href="./../../python-for-ai/provenance-and-oversight.html">Provenance/oversight</a>, <a href="./../../python-for-ai/provider-data-lifecycle.html">provider data lifecycle</a></td><td>Approval versus receipt versus trace; minimize export and inventory derivatives</td></tr></tbody></table><p>The <a href="./../../workbench/applied-ai/python/">Python workbench</a> contains the source displayed in these lessons. The pinned study environment is Python 3.13.11, OpenAI SDK 3.35.1, Pydantic 2.14.1 and LangGraph 1.2.17 where selected. These are reproducible fixture versions, not claims that they are the latest or account-enabled. Network behavior is tested through mock transports or owned loopback services; no real model quality follows from those tests.</p><h2 id="structured-output-and-tools-have-different-jobs" tabindex="-1">Structured output and tools have different jobs <a class="header-anchor" href="#structured-output-and-tools-have-different-jobs" aria-label="Permalink to “Structured output and tools have different jobs”">​</a></h2><p>Use a typed response schema when the output is application data, such as an answer/citation record. Use tool calling when a model proposes an application operation. In both cases validate complete output locally, check semantics/current authority and handle refusal/incomplete/transport failures before acceptance. Do not execute streamed argument fragments or “repair” incomplete JSON into a claimed success.</p><p>The existing Responses tool definition uses <code>strict: true</code>, required fields and <code>additionalProperties: false</code>. Provider-supported schema subsets differ from arbitrary application validators. On 2026-10-27 the <a href="https://developers.openai.com/api/docs/guides/function-calling" target="_blank" rel="noreferrer">official function-calling contract</a> and <a href="https://developers.openai.com/api/docs/guides/structured-outputs" target="_blank" rel="noreferrer">structured-output guidance</a> were rechecked. The retained pinned SDK is still tested locally; this round does not migrate models or depend on a named hosted model being available.</p><h2 id="keep-observations-and-authority-separate" tabindex="-1">Keep observations and authority separate <a class="header-anchor" href="#keep-observations-and-authority-separate" aria-label="Permalink to “Keep observations and authority separate”">​</a></h2><p>A trace says that a step was attempted or returned a projected outcome. A receipt answers what committed in its transaction domain. An approval records an authenticated decision for one exact command. A source hash identifies bytes. None substitutes for the others.</p><p>Example: a rename commits but its response is lost. The UI records an uncertain outcome, the trace records a timeout, and the authoritative receipt still records the mutation. Retrying with a new operation ID can cause a second effect. Recovery must inspect the original operation under current authority.</p><p>For evaluation, schema validity, citation validity, claim support, task completion and safe action are distinct measures. Reject a cheaper/faster candidate that violates a required safety invariant. Include failed/cancelled attempts, queue time and unknown usage; do not hide them by reporting only successful requests.</p><p><a href="./../../practice/applied-ai/">Shared practice and evidence</a> · <a href="./../rag/">Next: RAG</a></p>',13)])])}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
